from collections import Counter

def components(grid, bg):
    h,w=len(grid),len(grid[0]); seen=set(); out=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c]==bg or (r,c) in seen: continue
        color=grid[r][c]; comp={(r,c)}; seen.add((r,c)); stack=[(r,c)]
        while stack:
          y,x=stack.pop()
          for yy,xx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
              seen.add((yy,xx)); comp.add((yy,xx)); stack.append((yy,xx))
        out.append((color,comp))
    return out

def shape(comp):
    r0=min(r for r,c in comp); c0=min(c for r,c in comp)
    return frozenset((r-r0,c-c0) for r,c in comp)

def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps=components(grid,bg)
    # Locate the long L-shaped line marker, whose color is used for repainting.
    markers=[]
    for color,co in comps:
      for r,c in co:
        hor=[x for x in range(w) if (r,x) in co]
        ver=[y for y in range(h) if (y,c) in co]
        if len(hor)>=6 and len(ver)>=4:
          # Choose elbow with long perpendicular arms.
          markers.append((len(hor)+len(ver),color,r,c,hor,ver))
    if not markers: return out
    _,paint,er,ec,hor,ver=max(markers)
    right=max(hor)>ec; down=max(ver)>er
    # The target copy is in the quadrant opposite the marker's two arms.
    dr=-1 if down else 1
    dc=-1 if right else 1
    groups={}
    for color,co in comps:
      if color==paint or len(co)<2: continue
      groups.setdefault(shape(co),[]).append((color,co))
    matches=[]
    for sh,items in groups.items():
      if len(items)<2: continue
      for color,co in items:
        rs=[r for r,c in co];cs=[c for r,c in co]
        if (dr<0 and max(rs)>=er) or (dr>0 and min(rs)<=er): continue
        if (dc<0 and max(cs)>=ec) or (dc>0 and min(cs)<=ec): continue
        # choose closest duplicate pair in the desired quadrant
        dist=abs((max(rs) if dr<0 else min(rs))-er)+abs((max(cs) if dc<0 else min(cs))-ec)
        matches.append((-len(co),dist,color,co))
    if matches:
      _,_,_,target=min(matches)
      for r,c in target: out[r][c]=paint
    return out

